import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';
import db = require('../db');
import { encryptSecret, decryptSecret } from './app-crypto';

const context = (userId: number) => `caldav-password:${userId}`;
const hash = (password: string) => createHash('sha256').update(password, 'utf8').digest('hex');

/**
 * CalDAV passwords are random 192-bit secrets generated by the server, so a fast hash suffices for
 * verification. An encrypted copy lets the owner look the password up again in the profile.
 */
export async function calDavPassword(userId: number, regenerate = false): Promise<{ password: string; created_at: string }> {
  const existing = regenerate ? null : await db.caldav.find(userId);
  if (existing) {
    try { return { password: decryptSecret(existing.password_encrypted, context(userId)), created_at: existing.created_at }; }
    catch { /* A changed server key makes the old copy unreadable; issue a new password. */ }
  }
  const password = randomBytes(24).toString('base64url');
  const created_at = new Date().toISOString();
  await db.caldav.set({ user_id: userId, password_hash: hash(password), password_encrypted: encryptSecret(password, context(userId)), created_at });
  return { password, created_at };
}

/** Resolves Basic-auth credentials (username or e-mail plus CalDAV password) to the account. */
export async function verifyCalDav(login: string, password: string): Promise<{ id: number; username: string; language?: string | null } | null> {
  if (!login || !password || login.length > 254 || password.length > 200) return null;
  const user = await db.users.findByUsername(login) || (login.includes('@') ? await db.users.findByEmail(login) : null);
  const credential = user ? await db.caldav.find(Number(user.id)) : null;
  // Compare even without a stored credential so response times do not reveal accounts.
  const expected = Buffer.from(credential?.password_hash || hash(randomBytes(24).toString('base64url')), 'hex');
  const actual = Buffer.from(hash(password), 'hex');
  if (!user || !credential || !timingSafeEqual(expected, actual)) return null;
  return { id: Number(user.id), username: String(user.username), language: (user as { language?: string | null }).language };
}
